macro_rules! deps {
    () => {
        HighlightedRange!();
        HighlightMap!();
    };
}

macro_rules! highlight_branch_exit_points {
    () => {
        deps!();
        pub (crate) fn highlight_branch_exit_points (sema : & Semantics < '_ , RootDatabase > , token : SyntaxToken ,) -> FxHashMap < EditionedFileId , Vec < HighlightedRange > > { let mut highlights : HighlightMap = FxHashMap :: default () ; let push_to_highlights = | file_id , range , highlights : & mut HighlightMap | { if let Some (FileRange { file_id , range }) = original_frange (sema . db , file_id , range) { let hrange = HighlightedRange { category : ReferenceCategory :: empty () , range } ; highlights . entry (file_id) . or_default () . insert (hrange) ; } } ; let push_tail_expr = | tail : Option < ast :: Expr > , highlights : & mut HighlightMap | { let Some (tail) = tail else { return ; } ; for_each_tail_expr (& tail , & mut | tail | { let file_id = sema . hir_file_for (tail . syntax ()) ; let range = tail . syntax () . text_range () ; push_to_highlights (file_id , Some (range) , highlights) ; }) ; } ; let nodes = goto_definition :: find_branch_root (sema , & token) . into_iter () ; match token . kind () { T ! [match] => { for match_expr in nodes . filter_map (ast :: MatchExpr :: cast) { let file_id = sema . hir_file_for (match_expr . syntax ()) ; let range = match_expr . match_token () . map (| token | token . text_range ()) ; push_to_highlights (file_id , range , & mut highlights) ; let Some (arm_list) = match_expr . match_arm_list () else { continue ; } ; for arm in arm_list . arms () { push_tail_expr (arm . expr () , & mut highlights) ; } } } T ! [=>] => { for arm in nodes . filter_map (ast :: MatchArm :: cast) { let file_id = sema . hir_file_for (arm . syntax ()) ; let range = arm . fat_arrow_token () . map (| token | token . text_range ()) ; push_to_highlights (file_id , range , & mut highlights) ; push_tail_expr (arm . expr () , & mut highlights) ; } } T ! [if] => { for mut if_to_process in nodes . map (ast :: IfExpr :: cast) { while let Some (cur_if) = if_to_process . take () { let file_id = sema . hir_file_for (cur_if . syntax ()) ; let if_kw_range = cur_if . if_token () . map (| token | token . text_range ()) ; push_to_highlights (file_id , if_kw_range , & mut highlights) ; if let Some (then_block) = cur_if . then_branch () { push_tail_expr (Some (then_block . into ()) , & mut highlights) ; } match cur_if . else_branch () { Some (ast :: ElseBranch :: Block (else_block)) => { push_tail_expr (Some (else_block . into ()) , & mut highlights) ; if_to_process = None ; } Some (ast :: ElseBranch :: IfExpr (nested_if)) => if_to_process = Some (nested_if) , None => if_to_process = None , } } } } _ => { } } highlights . into_iter () . map (| (file_id , ranges) | (file_id , ranges . into_iter () . collect ())) . collect () }
    };
}

highlight_branch_exit_points!()